import React, { useState, useEffect } from 'react';
import { Box, Avatar, Typography, Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions, Button, CircularProgress, Badge } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import HomeIcon from '@mui/icons-material/Home';
import NotificationsIcon from '@mui/icons-material/Notifications';
import ArticleIcon from '@mui/icons-material/Article';
import LogoutIcon from '@mui/icons-material/Logout';
import { utilisateurService } from '../../services/utilisateurService';
import { notificationService } from '../../services/notificationService';

// Types
interface LeftMenuProps {
    utilisateur: {
        id: number;
        pseudo: string;
        photo_profil: string | null;
    };
    activeView: 'actualites' | 'mes_publications';
    onViewChange: (view: 'actualites' | 'mes_publications') => void;
}

interface MenuItemProps {
    icon: React.ReactNode;
    label: string;
    isActive: boolean;
    onClick: () => void;
}

// Styles constants
const MENU_ITEM_STYLES = {
    display: 'flex',
    alignItems: 'center',
    cursor: 'pointer',
    padding: '8px 12px',
    borderRadius: '12px',
    transition: 'all 0.3s ease',
    mb: 1,
    '&:hover': {
        background: 'rgba(119, 51, 153, 0.15)',
        transform: 'translateX(5px)'
    },
    '&:hover .menu-icon': { transform: 'scale(1.1)' },
    '&:hover .menu-text': { color: '#773399' }
} as const;

const LOGOUT_HOVER_STYLES = {
    '&:hover': {
        background: 'rgba(119, 51, 153, 0.15)',
        transform: 'translateX(5px)'
    },
    '&:hover .logout-icon': { color: '#773399' },
    '&:hover .logout-text': { color: '#773399' }
} as const;

const AVATAR_HOVER_STYLES = {
    '&:hover .avatar': {
        transform: 'scale(1.05)',
        boxShadow: '0 6px 15px rgba(119, 51, 153, 0.3)'
    },
    '&:hover .pseudo': {
        color: '#773399',
        textDecoration: 'underline'
    }
} as const;

const BUTTON_STYLES = {
    borderRadius: 45,
    borderColor: '#773399',
    color: '#773399',
    '&:hover': {
        borderColor: '#5a2a7a',
        color: '#5a2a7a',
        backgroundColor: 'rgba(119, 51, 153, 0.04)'
    }
} as const;

const CONTAINED_BUTTON_STYLES = {
    borderRadius: 45,
    backgroundColor: '#773399',
    '&:hover': { backgroundColor: '#5a2a7a' }
} as const;

const LEFT_MENU_SX = {
    width: 280,
    background: 'linear-gradient(180deg, #ffffff 1%, #cfcfcf 43%, #999999 100%)',
    height: '100vh',
    position: 'sticky',
    top: 0,
    flexShrink: 0,
    display: 'flex',
    flexDirection: 'column'
} as const;

const LOGO_BOX_SX = {
    display: 'flex',
    justifyContent: 'center',
    pt: 3,
    pb: 2
} as const;

const AVATAR_SX = {
    width: 86,
    height: 88,
    border: '3px solid white',
    boxShadow: '0 4px 10px rgba(0,0,0,0.2)',
    transition: 'transform 0.3s ease'
} as const;

const PSEUDO_SX = {
    fontFamily: 'Poppins',
    fontWeight: 600,
    fontSize: 16,
    color: '#333',
    textAlign: 'center',
    mt: 2,
    transition: 'all 0.3s ease'
} as const;

const MENU_CONTAINER_SX = {
    flex: 1,
    px: 3,
    mt: 2
} as const;

const LOGOUT_CONTAINER_SX = {
    px: 3,
    pb: 4,
    mt: 'auto'
} as const;

const LOGOUT_BOX_SX = {
    display: 'flex',
    alignItems: 'center',
    cursor: 'pointer',
    padding: '8px 12px',
    borderRadius: '12px',
    transition: 'all 0.3s ease',
    ...LOGOUT_HOVER_STYLES
} as const;

const LOGOUT_ICON_SX = {
    width: 32,
    height: 32,
    color: '#666',
    transition: 'color 0.3s ease'
} as const;

const LOGOUT_TEXT_SX = {
    ml: 2,
    fontFamily: 'Poppins',
    fontWeight: 600,
    fontSize: 16,
    color: '#333',
    transition: 'color 0.3s ease'
} as const;

// Composant MenuItem
const MenuItem: React.FC<MenuItemProps> = ({ icon, label, isActive, onClick }) => (
    <Box onClick={onClick} sx={{
        ...MENU_ITEM_STYLES,
        background: isActive ? 'rgba(119, 51, 153, 0.2)' : 'transparent',
        borderLeft: isActive ? '3px solid #773399' : '3px solid transparent'
    }}>
        <Box className="menu-icon" sx={{
            width: 32, height: 32,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: isActive ? '#773399' : '#666',
            transition: 'transform 0.3s ease'
        }}>
            {icon}
        </Box>
        <Typography className="menu-text" sx={{
            ml: 2, fontFamily: 'Poppins',
            fontWeight: isActive ? 700 : 600, fontSize: 16,
            color: isActive ? '#773399' : '#333',
            transition: 'color 0.3s ease'
        }}>
            {label}
        </Typography>
    </Box>
);

// Composant principal
const LeftMenu: React.FC<LeftMenuProps> = ({ utilisateur, activeView, onViewChange }) => {
    const navigate = useNavigate();
    const [logoutDialogOpen, setLogoutDialogOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [nonLuCount, setNonLuCount] = useState(0);

    // Récupérer le nombre de notifications non lues
    useEffect(() => {
        const fetchNonLuCount = async () => {
            try {
                const response = await notificationService.getNonLuCount();
                setNonLuCount(response.data.count);
            } catch (error) {
                console.error('Erreur lors du chargement du nombre de notifications', error);
            }
        };
        fetchNonLuCount();
        const interval = setInterval(fetchNonLuCount, 30000);
        return () => clearInterval(interval);
    }, []);

    const handleLogout = async () => {
        setLoading(true);
        try {
            await utilisateurService.deconnexion();
            sessionStorage.clear();
            navigate('/login');
        } catch (error) {
            console.error('Erreur lors de la déconnexion', error);
        } finally {
            setLoading(false);
            setLogoutDialogOpen(false);
        }
    };

    const avatarUrl = utilisateur.photo_profil
        ? `http://localhost:8080/uploads/${utilisateur.photo_profil}`
        : '/icons/green.jpg';

    const menuItems = [
        { icon: <HomeIcon />, label: 'Actualités', key: 'actualites' as const },
        { 
            icon: <Badge badgeContent={nonLuCount} color="error"><NotificationsIcon /></Badge>, 
            label: 'Notification', 
            key: 'notification' as const, 
            action: () => navigate('/notifications') 
        },
        { icon: <ArticleIcon />, label: 'Mes publications', key: 'mes_publications' as const }
    ];

    const handleProfilClick = () => navigate('/profil/settings');

    return (
        <>
            <Box sx={LEFT_MENU_SX}>
                {/* Logo */}
                <Box sx={LOGO_BOX_SX}>
                    <img src="/icons/logo.png" alt="Logo" style={{ width: 199, height: 122 }} />
                </Box>

                {/* Profil cliquable */}
                <Box onClick={handleProfilClick} sx={{
                    display: 'flex', flexDirection: 'column', alignItems: 'center',
                    mt: 2, mb: 2, cursor: 'pointer', transition: 'all 0.3s ease',
                    ...AVATAR_HOVER_STYLES
                }}>
                    <Avatar src={avatarUrl} className="avatar" sx={AVATAR_SX} />
                    <Typography className="pseudo" sx={PSEUDO_SX}>
                        @{utilisateur.pseudo}
                    </Typography>
                </Box>

                {/* Menu items */}
                <Box sx={MENU_CONTAINER_SX}>
                    {menuItems.map(item => (
                        <MenuItem
                            key={item.key}
                            icon={item.icon}
                            label={item.label}
                            isActive={activeView === item.key}
                            onClick={() => item.action ? item.action() : onViewChange(item.key)}
                        />
                    ))}
                </Box>

                {/* Déconnexion */}
                <Box sx={LOGOUT_CONTAINER_SX}>
                    <Box onClick={() => setLogoutDialogOpen(true)} sx={LOGOUT_BOX_SX}>
                        <LogoutIcon className="logout-icon" sx={LOGOUT_ICON_SX} />
                        <Typography className="logout-text" sx={LOGOUT_TEXT_SX}>
                            Se déconnecter
                        </Typography>
                    </Box>
                </Box>
            </Box>

            {/* Dialogue de confirmation */}
            <Dialog open={logoutDialogOpen} onClose={() => setLogoutDialogOpen(false)}>
                <DialogTitle sx={{ fontFamily: 'Poppins', fontWeight: 600 }}>Déconnexion</DialogTitle>
                <DialogContent>
                    <DialogContentText sx={{ fontFamily: 'Poppins' }}>
                        Êtes-vous sûr de vouloir vous déconnecter ?
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setLogoutDialogOpen(false)} sx={BUTTON_STYLES}>Annuler</Button>
                    <Button onClick={handleLogout} disabled={loading} variant="contained" sx={CONTAINED_BUTTON_STYLES}>
                        {loading ? <CircularProgress size={24} color="inherit" /> : 'Se déconnecter'}
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
};

export default LeftMenu;
